logger = logging.getLogger(__name__)


@triton.jit
def _logical_offset(linear, shapes: tl.constexpr, strides: tl.constexpr):
    offset = linear * 0
    for axis in tl.static_range(len(shapes) - 1, -1, -1):
        coordinate = linear % shapes.value[axis]
        linear = linear // shapes.value[axis]
        offset += coordinate * strides.value[axis]
    return offset


@triton.jit
def angle_backward_kernel(
    grad_output,
    inp_real,
    inp_imag,
    out_real,
    out_imag,
    n_elements,
    SHAPE: tl.constexpr,
    GRAD_STRIDES: tl.constexpr,
    INPUT_STRIDES: tl.constexpr,
    OUTPUT_STRIDES: tl.constexpr,
    IS_COMPLEX: tl.constexpr,
    IS_COMPLEX_HALF: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    logical = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = logical < n_elements
    output_offset = _logical_offset(logical, SHAPE, OUTPUT_STRIDES)
    if IS_COMPLEX:
        input_offset = _logical_offset(logical, SHAPE, INPUT_STRIDES)
        grad_offset = _logical_offset(logical, SHAPE, GRAD_STRIDES)
        real = tl.load(inp_real + input_offset, mask=mask).to(tl.float32)
        imag = tl.load(inp_imag + input_offset, mask=mask).to(tl.float32)
        grad = tl.load(grad_output + grad_offset, mask=mask).to(tl.float32)
        magnitude = tl.sqrt(real * real + imag * imag)
        if IS_COMPLEX_HALF:
            magnitude = magnitude.to(tl.float16).to(tl.float32)
        squared_abs = magnitude * magnitude
        if IS_COMPLEX_HALF:
            squared_abs = squared_abs.to(tl.float16).to(tl.float32)
        real_grad = tl.where(squared_abs == 0.0, 0.0, -grad * imag / squared_abs)
        imag_grad = tl.where(squared_abs == 0.0, 0.0, grad * real / squared_abs)
        tl.store(out_real + output_offset, real_grad, mask=mask)
        tl.store(out_imag + output_offset, imag_grad, mask=mask)
    else:
        tl.store(out_real + output_offset, 0.0, mask=mask)


def angle_backward(grad_output, inp):
    """Compute the angle adjoint with one tiled Triton kernel."""
    logger.debug("GEMS ANGLE_BACKWARD")
    is_complex = inp.dtype in (torch.complex32, torch.complex64)
    grad_input = torch.empty_like(inp)
    if is_complex:
        inp_real = inp.real
        inp_imag = inp.imag
        out_real = grad_input.real
        out_imag = grad_input.imag
    else:
        inp_real = inp
        inp_imag = inp
        out_real = grad_input
        out_imag = grad_input

    n_elements = inp.numel()
    # 256 elements balance occupancy and launch count for this pointwise adjoint.
    block_size = 256
    grid = (triton.cdiv(n_elements, block_size),)
    with torch_device_fn.device(inp.device):
        angle_backward_kernel[grid](
            grad_output,
            inp_real,
            inp_imag,
            out_real,
            out_imag,
            n_elements,
            SHAPE=tuple(inp.shape),
            GRAD_STRIDES=tuple(grad_output.stride()),
            INPUT_STRIDES=tuple(inp_real.stride()),
            OUTPUT_STRIDES=tuple(out_real.stride()),
            IS_COMPLEX=is_complex,
            IS_COMPLEX_HALF=inp.dtype == torch.complex32,
            BLOCK_SIZE=block_size,
            num_warps=4,
        )
    return grad_input


